/**
 * @brief Map hardware port index to actual GPIO number
 *
 * Converts a port index (0-9) to the actual GPIO pin number using compile-time defines
 * from platformio.hardware.ini (NEOPIXEL_HW_PORT_N_GPIO).
 *
 * Port indices map to NEOPIXEL_HW_PORT_{index+1}_GPIO defines:
 * - Index 0 → NEOPIXEL_HW_PORT_1_GPIO
 * - Index 1 → NEOPIXEL_HW_PORT_2_GPIO
 * - etc.
 *
 * @param portIndex Port index (0-9) from ETS parameter
 * @return Actual GPIO pin number, or 255 if invalid/not defined
 */
inline uint8_t mapPortIndexToGpio(uint8_t portIndex)
{
    // Port indices 0-9 map to NEOPIXEL_HW_PORT_1_GPIO through NEOPIXEL_HW_PORT_10_GPIO
    switch (portIndex)
    {
#ifdef NEOPIXEL_HW_PORT_1_GPIO
        case 0: return NEOPIXEL_HW_PORT_1_GPIO;
#endif
#ifdef NEOPIXEL_HW_PORT_2_GPIO
        case 1: return NEOPIXEL_HW_PORT_2_GPIO;
#endif
#ifdef NEOPIXEL_HW_PORT_3_GPIO
        case 2: return NEOPIXEL_HW_PORT_3_GPIO;
#endif
#ifdef NEOPIXEL_HW_PORT_4_GPIO
        case 3: return NEOPIXEL_HW_PORT_4_GPIO;
#endif
#ifdef NEOPIXEL_HW_PORT_5_GPIO
        case 4: return NEOPIXEL_HW_PORT_5_GPIO;
#endif
#ifdef NEOPIXEL_HW_PORT_6_GPIO
        case 5: return NEOPIXEL_HW_PORT_6_GPIO;
#endif
#ifdef NEOPIXEL_HW_PORT_7_GPIO
        case 6: return NEOPIXEL_HW_PORT_7_GPIO;
#endif
#ifdef NEOPIXEL_HW_PORT_8_GPIO
        case 7: return NEOPIXEL_HW_PORT_8_GPIO;
#endif
#ifdef NEOPIXEL_HW_PORT_9_GPIO
        case 8: return NEOPIXEL_HW_PORT_9_GPIO;
#endif
#ifdef NEOPIXEL_HW_PORT_10_GPIO
        case 9: return NEOPIXEL_HW_PORT_10_GPIO;
#endif
        default: return INVALID_GPIO;
    }
}

/**
 * @brief Check if hardware-assisted GPIO mode is active
 *
 * Returns true if a valid hardware port is selected (not manual, not dummy).
 *
 * @param portSelection Port-selection value from getDataPortSelectionForHardwareIndex()
 *                      or getClockPortSelectionForHardwareIndex()
 * @return true if hardware port is selected, false if manual (10) or dummy (15)
 */
inline bool isHardwarePortSelected(uint8_t portSelection)
{
    return portSelection <= MAX_HARDWARE_PORT_INDEX;
}

/**
 * @brief Get actual GPIO number for data port
 *
 * High-level function that:
 * 1. Checks if manual mode is enabled
 * 2. If not manual, reads hardware-specific port index
 * 3. Maps port index to actual GPIO number
 *
 * @param stripIndex Strip index (1-based)
 * @param manualGpio Manual GPIO number (from ParamNEOSTRIP_NEODataGPIO)
 * @param isManual Manual mode flag (from ParamNEOSTRIP_NEOGPIOManual)
 * @return Actual GPIO pin number
 */
inline uint8_t getActualDataGpio(uint8_t stripIndex, uint8_t manualGpio, bool isManual)
{
    if (isManual)
    {
        return manualGpio;
    }

    uint8_t portIndex = getDataPortSelectionForHardwareIndex(stripIndex);
    if (isHardwarePortSelected(portIndex))
    {
        return mapPortIndexToGpio(portIndex);
    }

    // Fallback to manual GPIO if hardware port not properly selected
    return manualGpio;
}

/**
 * @brief Get actual GPIO number for clock port (SPI only)
 *
 * Similar to getActualDataGpio but for clock pins.
 *
 * @param stripIndex Strip index (1-based)
 * @param manualGpio Manual GPIO number (from ParamNEOSTRIP_NEOClockGPIO)
 * @param isManual Manual mode flag (from ParamNEOSTRIP_NEOGPIOManual)
 * @return Actual GPIO pin number
 */
inline uint8_t getActualClockGpio(uint8_t stripIndex, uint8_t manualGpio, bool isManual)
{
    if (isManual)
    {
        return manualGpio;
    }

    uint8_t portIndex = getClockPortSelectionForHardwareIndex(stripIndex);
    if (isHardwarePortSelected(portIndex))
    {
        return mapPortIndexToGpio(portIndex);
    }

    // Fallback to manual GPIO if hardware port not properly selected
    return manualGpio;
}
